svg.script:

document.addEventListener("DOMContentLoaded", () => {
  // REPLACE WITH YOUR ACTUAL GITHUB RAW URL
  const gitHubRawUrl = "https://githubusercontent.com";

  fetch(gitHubRawUrl)
    .then(response => {
      if (!response.ok) {
        throw new Error(`HTTP network error! Status: ${response.status}`);
      }
      return response.text();
    })
    .then(htmlData => {
      // Target the inner container and securely inject the fetched markup
      const container = document.getElementById("content-target");
      if (container) {
        container.innerHTML = htmlData;
      }
    })
    .catch(error => {
      console.error("Failed to fetch or inject content:", error);
      const container = document.getElementById("content-target");
      if (container) {
        container.innerHTML = `<p style="color: red; padding: 10px;">Error loading content.</p>`;
      }
    });
});
